from PIL import Image
p='/home/amao/nextkde/tmp/ui-acceptance/calendar/r121-sidebar-light.png'
im=Image.open(p).convert('RGB'); px=im.load(); w,h=im.size
targets={'green':(72,208,93),'yellow':(254,198,77),'red':(255,119,112)}
for name,t in targets.items():
    xs=[];ys=[]
    for y in range(0,60):
        for x in range(900,w):
            q=px[x,y]
            if abs(q[0]-t[0])<=6 and abs(q[1]-t[1])<=6 and abs(q[2]-t[2])<=6:
                xs.append(x);ys.append(y)
    if xs:
        print(name,'x',min(xs),max(xs),'w',max(xs)-min(xs)+1,'y',min(ys),max(ys),'h',max(ys)-min(ys)+1,'n',len(xs))
    else: print(name,'none')
# row profile at disc vertical centre to get exact edges incl. antialias
print('--- scan row y=17 x1000..1100')
for y in (16,17,18):
    row=[]
    prev=None
    for x in range(1000,w):
        q=px[x,y]
        s=max(q)-min(q)
        c='.' if s<=6 else ('G' if q[1]>q[0] and q[1]>q[2] else ('Y' if q[0]>200 and q[1]>150 and q[2]<120 else 'R'))
        row.append(c)
    print(y,''.join(row))
